: \"7starsseeker\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/7starsseeker/dsh-fact-check.git\"\n  },\n  \"homepage\": \"https://github.com/7starsseeker/dsh-fact-check#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/7starsseeker/dsh-fact-check/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  }\n}\n"
